def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    best = None
    for _ in range(budget):
        x = clip(rng.normal(loc=0, scale=1.5, size=(dim,)))
        fx = func(x)
        if best is None or fx < func(best):
            best = x
    return best
